<script setup lang="ts">
import { onMounted, reactive, shallowRef } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { getAdminFacingError } from '../../../app/auth'
import { agricultureAdminApi } from '../api/agriculture'
import type { Crop, Knowledge, KnowledgeInput } from '../types/agriculture'
const items = shallowRef<Knowledge[]>([]); const crops = shallowRef<Crop[]>([]); const loading = shallowRef(false); const dialogVisible = shallowRef(false); const editorLoading = shallowRef(false); const editingId = shallowRef<number | null>(null); const keyword = shallowRef('')
const form = reactive({ title: '', summary: '', content: '', category: '种植管理', tagsText: '', regionCodesText: '', isGeneral: false, sourceName: '', sourceUrl: '', validUntil: '', cropIds: [] as number[] })
function clearForm(): void { Object.assign(form, { title: '', summary: '', content: '', category: '种植管理', tagsText: '', regionCodesText: '', isGeneral: false, sourceName: '', sourceUrl: '', validUntil: '', cropIds: [] }) }
function toInput(): KnowledgeInput { return { title: form.title.trim(), summary: form.summary.trim() || undefined, content: form.content.trim(), category: form.category.trim(), tags: form.tagsText.split(/[,，]/).map(item => item.trim()).filter(Boolean), regionCodes: form.regionCodesText.split(/[,，]/).map(item => item.trim()).filter(Boolean), isGeneral: form.isGeneral, sourceName: form.sourceName.trim() || undefined, sourceUrl: form.sourceUrl.trim() || undefined, validUntil: form.validUntil || undefined, cropIds: form.cropIds } }
async function load(): Promise<void> { loading.value = true; try { items.value = (await agricultureAdminApi.knowledge({ keyword: keyword.value.trim() || undefined })).list } catch (error) { ElMessage.error(getAdminFacingError(error)) } finally { loading.value = false } }
async function loadCrops(): Promise<void> { try { crops.value = await agricultureAdminApi.crops() } catch (error) { ElMessage.error(getAdminFacingError(error)) } }
function create(): void { editingId.value = null; clearForm(); dialogVisible.value = true }
async function edit(item: Knowledge): Promise<void> { editorLoading.value = true; try { const detail = await agricultureAdminApi.knowledgeDetail(item.id); editingId.value = item.id; Object.assign(form, { title: detail.title, summary: detail.summary ?? '', content: detail.content ?? '', category: detail.category, tagsText: detail.tags.join('，'), regionCodesText: detail.regionCodes.join('，'), isGeneral: detail.isGeneral, sourceName: detail.sourceName ?? '', sourceUrl: detail.sourceUrl ?? '', validUntil: detail.validUntil ?? '', cropIds: detail.cropIds }); dialogVisible.value = true } catch (error) { ElMessage.error(getAdminFacingError(error)) } finally { editorLoading.value = false } }
async function save(): Promise<void> { const input = toInput(); if (!input.title || !input.content || !input.category) return; try { if (editingId.value) await agricultureAdminApi.updateKnowledge(editingId.value, input); else await agricultureAdminApi.createKnowledge(input); ElMessage.success('知识内容已保存'); dialogVisible.value = false; await load() } catch (error) { ElMessage.error(getAdminFacingError(error)) } }
async function changeStatus(item: Knowledge, action: 'publish' | 'archive'): Promise<void> { try { if (action === 'publish') await agricultureAdminApi.publishKnowledge(item.id); else await agricultureAdminApi.archiveKnowledge(item.id); ElMessage.success(action === 'publish' ? '已发布' : '已归档'); await load() } catch (error) { ElMessage.error(getAdminFacingError(error)) } }
async function remove(item: Knowledge): Promise<void> { try { await ElMessageBox.confirm(`确定软删除“${item.title}”吗？`, '删除知识', { type: 'warning' }); await agricultureAdminApi.deleteKnowledge(item.id); ElMessage.success('已删除'); await load() } catch (error) { if (error !== 'cancel') ElMessage.error(getAdminFacingError(error)) } }
onMounted(() => { void load(); void loadCrops() })
</script>
<template><section class="knowledge-manager"><div class="toolbar"><div><h2>农业知识维护</h2><p>草稿、发布和归档均以服务端状态为准。</p></div><div class="actions"><el-input v-model="keyword" placeholder="搜索标题或正文" clearable @keyup.enter="load" /><el-button @click="load">搜索</el-button><el-button type="primary" @click="create">新建知识</el-button></div></div><el-table v-loading="loading" :data="items" stripe><el-table-column prop="title" label="标题" min-width="220" show-overflow-tooltip /><el-table-column prop="category" label="分类" width="120" /><el-table-column label="状态" width="100"><template #default="{ row }"><el-tag :type="row.status === 'published' ? 'success' : row.status === 'draft' ? 'info' : 'warning'">{{ row.status === 'draft' ? '草稿' : row.status === 'published' ? '已发布' : '已归档' }}</el-tag></template></el-table-column><el-table-column prop="version" label="版本" width="80" /><el-table-column label="操作" width="260"><template #default="{ row }"><el-button link type="primary" @click="edit(row)">编辑</el-button><el-button v-if="row.status === 'draft'" link type="success" @click="changeStatus(row, 'publish')">发布</el-button><el-button v-if="row.status === 'published'" link type="warning" @click="changeStatus(row, 'archive')">归档</el-button><el-button v-if="row.status !== 'published'" link type="danger" @click="remove(row)">删除</el-button></template></el-table-column></el-table><el-dialog v-model="dialogVisible" :title="editingId ? '编辑农业知识' : '新建农业知识'" width="760" :close-on-click-modal="false"><el-form v-loading="editorLoading" label-width="94px"><el-form-item label="标题" required><el-input v-model="form.title" maxlength="255" /></el-form-item><el-form-item label="摘要"><el-input v-model="form.summary" type="textarea" maxlength="500" /></el-form-item><el-form-item label="正文" required><el-input v-model="form.content" type="textarea" :rows="8" maxlength="20000" /></el-form-item><el-form-item label="分类" required><el-select v-model="form.category" allow-create filterable><el-option v-for="category in ['种植管理','病虫害','土肥管理','气象风险','采收储存']" :key="category" :value="category" /></el-select></el-form-item><el-form-item label="标签"><el-input v-model="form.tagsText" placeholder="使用逗号分隔" /></el-form-item><el-form-item label="关联作物"><el-select v-model="form.cropIds" multiple clearable><el-option v-for="crop in crops" :key="crop.id" :label="crop.name" :value="crop.id" /></el-select><el-checkbox v-model="form.isGeneral" class="general">通用知识</el-checkbox></el-form-item><el-form-item label="适用地区"><el-input v-model="form.regionCodesText" placeholder="地区编码以逗号分隔；留空表示不限制" /></el-form-item><el-form-item label="来源名称"><el-input v-model="form.sourceName" maxlength="255" /></el-form-item><el-form-item label="来源链接"><el-input v-model="form.sourceUrl" maxlength="1000" /></el-form-item><el-form-item label="有效期"><el-date-picker v-model="form.validUntil" type="date" value-format="YYYY-MM-DD" /></el-form-item></el-form><template #footer><el-button @click="dialogVisible = false">取消</el-button><el-button type="primary" @click="save">保存草稿</el-button></template></el-dialog></section></template>
<style scoped>.knowledge-manager { padding: 24px; }.toolbar { display: flex; align-items: center; justify-content: space-between; gap: 24px; margin-bottom: 20px; }.toolbar h2 { margin: 0 0 6px; font-size: 20px; }.toolbar p { color: var(--color-text-secondary); font-size: 14px; }.actions { display: flex; gap: 8px; }.general { margin-left: 16px; }</style>
